changeSet.sql:
ALTER TABLE user_role_assignments
DROP CONSTRAINT chk_assignments_scope_type;

ALTER TABLE user_role_assignments
ADD CONSTRAINT chk_assignments_scope_type
CHECK (scope_type IN ('TENANT', 'BRANCH', 'WAREHOUSE'));

ALTER TABLE user_role_assignments
DROP CONSTRAINT chk_assignments_scope_branch;

ALTER TABLE user_role_assignments
ADD CONSTRAINT chk_assignments_scope_branch
CHECK (
    (scope_type = 'TENANT' AND branch_id IS NULL AND warehouse_id IS NULL) OR
    (scope_type = 'BRANCH' AND branch_id IS NOT NULL AND warehouse_id IS NULL) OR
    (scope_type = 'WAREHOUSE' AND warehouse_id IS NOT NULL AND branch_id IS NULL)
);

CREATE UNIQUE INDEX uq_assignments_active_warehouse
ON user_role_assignments (tenant_id, membership_id, role_id, warehouse_id)
WHERE is_active = TRUE AND scope_type = 'WAREHOUSE';

CREATE INDEX idx_assignments_tenant_wh_active
ON user_role_assignments (tenant_id, warehouse_id, is_active)
WHERE warehouse_id IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS idx_assignments_tenant_wh_active;
DROP INDEX IF EXISTS uq_assignments_active_warehouse;

ALTER TABLE user_role_assignments DROP CONSTRAINT chk_assignments_scope_branch;
ALTER TABLE user_role_assignments ADD CONSTRAINT chk_assignments_scope_branch
CHECK (
    (scope_type = 'TENANT' AND branch_id IS NULL) OR
    (scope_type = 'BRANCH' AND branch_id IS NOT NULL)
);

ALTER TABLE user_role_assignments DROP CONSTRAINT chk_assignments_scope_type;
ALTER TABLE user_role_assignments ADD CONSTRAINT chk_assignments_scope_type
CHECK (scope_type IN ('TENANT', 'BRANCH'));
